method.description:
Converts Godot data to YAML text. Returns a [YAMLResult] containing either the generated YAML string or error information.
If [param style] is provided, it will be used to customize the formatting of the YAML output. Otherwise, default formatting will be used.
[codeblocks]
[gdscript]
# Basic serialization
var data = {
    "name": "Stranger",
    "dialogue": ["Hello, traveler.", "What brings you here?"]
}

# Convert to YAML
var stringify_result = YAML.stringify(data)
if stringify_result.has_error():
    print("Error: ", stringify_result.get_error_message())
else:
    var yaml = stringify_result.get_data()
    print(yaml)
    # Output:
    # name: Stranger
    # dialogue:
    #   - "Hello, traveler."
    #   - "What brings you here?"

# Serialization with custom style
var style = YAML.create_style()
style.set_flow_style(YAMLStyle.FLOW_SINGLE)
style.set_quote_style(YAMLStyle.QUOTE_DOUBLE)

var styled_result = YAML.stringify(data, style)
if !styled_result.has_error():
    var yaml = styled_result.get_data()
    print(yaml)
    # Output:
    # name: "Stranger"
    # dialogue: ["Hello, traveler.", "What brings you here?"]

# Serializing nested structures with different styles
var nested_data = {
    "config": {
        "debug": true,
        "volume": 0.8
    },
    "levels": ["Level1", "Level2", "Level3"]
}

var nested_style = YAML.create_style()

# Create a child style for the config
var config_style = YAML.create_style()
config_style.set_flow_style(YAMLStyle.FLOW_SINGLE)
nested_style.set_child("config", config_style)

var nested_result = YAML.stringify(nested_data, nested_style)
if !nested_result.has_error():
    var yaml = nested_result.get_data()
    print(yaml)
    # Output:
    # config: {debug: true, volume: 0.8}
    # levels:
    #   - Level1
    #   - Level2
    #   - Level3
[/gdscript]
[/codeblocks]
